import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    INF = n + 1

    # For each possible maximum x and left endpoint l, store the
    # minimum right endpoint of a condition with X=x and L>=l.
    min_right = [[INF] * (n + 2) for _ in range(n + 1)]
    p = 2
    for _ in range(m):
        L, R, X = data[p], data[p + 1], data[p + 2]
        p += 3
        if R < min_right[X][L]:
            min_right[X][L] = R

    for x in range(1, n + 1):
        row = min_right[x]
        for l in range(n - 1, 0, -1):
            if row[l + 1] < row[l]:
                row[l] = row[l + 1]

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                # A condition contained in [l,r] and having X=k
                # would be violated when k is the largest element.
                if min_right[k][l] <= r:
                    continue
                total = (total + comb[length - 1][k - l]
                         * dp[l][k - 1] * dp[k + 1][r]) % MOD
            dp[l][r] = total

    print(dp[1][n])

if __name__ == '__main__':
    main()

