import sys

MOD = 998244353

def factor(x):
    d = 2
    r = {}
    while d * d <= x:
        while x % d == 0:
            r[d] = r.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        r[x] = r.get(x, 0) + 1
    return r

def contribution(p, exponents):
    total = sum(exponents)
    pw = [1] * (total + 1)
    for i in range(1, total + 1):
        pw[i] = pw[i - 1] * p % MOD

    # nt: paths whose minimum is not reached yet; tt: paths that reached 0
    # The initial height ranges from 0 through total; larger heights cannot
    # reach zero in the remaining steps.
    nt = [0] * (total + 1)
    tt = [0] * (total + 1)
    for h in range(1, total + 1):
        nt[h] = pw[h]
    tt[0] = 1

    for e in exponents:
        new_nt = [0] * (total + 1)
        new_tt = [0] * (total + 1)
        for v in range(total + 1):
            for old, reached in ((nt, False), (tt, True)):
                value = old[v]
                if not value:
                    continue
                targets = (v,) if e == 0 else (v - e, v + e)
                for nv in targets:
                    if nv < 0 or nv > total:
                        continue
                    add = value * pw[nv] % MOD
                    if reached or nv == 0:
                        new_tt[nv] = (new_tt[nv] + add) % MOD
                    else:
                        new_nt[nv] = (new_nt[nv] + add) % MOD
        nt, tt = new_nt, new_tt
    return sum(tt) % MOD

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    factored = [factor(x) for x in a]
    primes = set()
    for f in factored:
        primes.update(f)

    answer = 1
    for p in primes:
        exponents = [f.get(p, 0) for f in factored]
        answer = answer * contribution(p, exponents) % MOD
    print(answer)

if __name__ == '__main__':
    main()

