from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            events[b].append((a, i))

        # The two largest active left endpoints, with their pair indices.
        best_a = best_i = second_a = second_i = 0
        base = 0
        gain = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for a, i in events[right]:
                if a > best_a:
                    second_a, second_i = best_a, best_i
                    best_a, best_i = a, i
                elif a > second_a:
                    second_a, second_i = a, i

            # Starts best_a + 1 through right are valid for this endpoint.
            base += right - best_a
            if best_a:
                # Removing the currently strongest pair lowers the restriction
                # by best_a - second_a for this endpoint.
                gain[best_i] += best_a - second_a

        return base + max(gain)

