class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # depth[x] is the number of operations needed to reduce x to 1.
        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            depth[x] = 1 + depth[x.bit_count()]

        # A number with c set bits needs one operation to become c,
        # followed by depth[c] operations.
        good = [False] * (n + 1)
        for c in range(1, n + 1):
            good[c] = (depth[c] + 1 <= k)

        # Binomial coefficients for choosing set bits in a suffix.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # At each 1 in s, numbers smaller than s can first differ there
        # by placing a zero. Choose the remaining set bits in the suffix.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for total in range(1, n + 1):
                    if good[total] and total >= prefix_ones:
                        needed = total - prefix_ones
                        if needed <= remaining:
                            answer = (answer + comb[remaining][needed]) % MOD
                prefix_ones += 1

        return answer

