import sys,heapq

def solve():
    it=iter(map(int,sys.stdin.buffer.read().split()))
    N=next(it); M=next(it); Q=next(it)
    seg=[[] for _ in range(4*N+5)]
    ans=[M+1]*M
    intervals=[]
    def add(node,l,r,ql,qr,val,typ):
        if ql<=l and r<=qr:
            heapq.heappush(seg[node],(val,typ)); return
        mid=(l+r)//2
        if ql<=mid: add(node*2,l,mid,ql,qr,val,typ)
        if qr>mid: add(node*2+1,mid+1,r,ql,qr,val,typ)
    def point(pos,lim,typ,idx):
        node=1;l=1;r=N
        while True:
            h=seg[node]
            while h and h[0][0] < lim:
                v,t=heapq.heappop(h)
                if t==typ: ans[v]=idx
            if l==r: break
            mid=(l+r)//2
            if pos<=mid: node=node*2;r=mid
            else: node=node*2+1;l=mid+1
    same={}
    for i in range(M):
        s=next(it); t=next(it)
        a,b=sorted((s,t)); intervals.append((a,b,s<t))
        key=(a,b)
        if key in same and same[key] != (s<t):
            ans[same[key]]=i; ans[i]=i
        else: same[key]=i
        # prior intervals crossing current [a,b]
        if a+1<=b-1:
            point(a+1,b,0,i) # prior b < current right, covering current left
            point(b-1,a,1,i) # prior a < current left, containing current right
        # add current for future: range of interior points, keyed right / left
        if a+1<=b-1:
            add(1,1,N,a+1,b-1,b,0)
            add(1,1,N,a+1,b-1,a,1)
    # range minimum query on ans
    size=1
    while size<M: size*=2
    st=[M+1]*(2*size); st[size:size+M]=ans
    for k in range(size-1,0,-1): st[k]=min(st[2*k],st[2*k+1])
