import sys
import heapq

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    g = [x.decode() for x in data[1:]]
    INF = 10**9
    dist = [[INF] * n for _ in range(n)]
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    heap = []
    finite = 0
    max_dist = 0

    for i in range(n):
        dist[i][i] = 0
        finite += 1
        heapq.heappush(heap, (0, i, i))
        for j, ch in enumerate(g[i]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    finite += 1
                    max_dist = 1
                    heapq.heappush(heap, (1, i, j))

    while heap:
        d, u, v = heapq.heappop(heap)
        if d != dist[u][v]:
            continue
        nd = d + 2
        # If every pair already has a value no greater than nd, this
        # state's extensions cannot improve anything.
        if finite == n * n and max_dist <= nd:
            continue
        for c in range(26):
            for x in incoming[u][c]:
                row = dist[x]
                for y in outgoing[v][c]:
                    if nd < row[y]:
                        if row[y] == INF:
                            finite += 1
                        row[y] = nd
                        if nd > max_dist:
                            max_dist = nd
                        heapq.heappush(heap, (nd, x, y))

    for row in dist:
        print(*(-1 if x == INF else x for x in row))

if __name__ == '__main__':
    main()

