import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    upper = vals[0::2]
    lower = vals[1::2]

    def feasible(h):
        lo = max(0, h - lower[0])
        hi = min(upper[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            lo = max(0, h - lower[i], lo - x)
            hi = min(upper[i], h, hi + x)
            if lo > hi:
                return False
        return True

    left = 0
    right = min(u + d for u, d in zip(upper, lower)) + 1
    while right - left > 1:
        mid = (left + right) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid

    print(sum(upper) + sum(lower) - n * left)


if __name__ == "__main__":
    solve()

