import sys,bisect

def main():
    z=list(map(int,sys.stdin.buffer.read().split()))
    if not z:
        return
    N,M,X1=z[:3]
    p=3
    trains=[]
    for _ in range(M):
        trains.append(tuple(z[p:p+4]))
        p+=4

    # For each city, store arrival times of trains ending there and a
    # Fenwick tree of the maximum delayed arrival seen so far.
    times={}
    for A,B,S,T in trains:
        times.setdefault(B,[]).append(T)
    fenwick={}
    for city,v in times.items():
        v.sort()
        fenwick[city]=[0]*(len(v)+1)

    def update(city,k,value):
        tree=fenwick[city]
        while k < len(tree):
            if value > tree[k]:
                tree[k]=value
            k += k & -k

    def maximum(city,k):
        tree=fenwick.get(city)
        result=0
        while k:
            if tree[k] > result:
                result=tree[k]
            k -= k & -k
        return result

    delays=[0]*M
    for i in sorted(range(M), key=lambda i: trains[i][2]):
        A,B,S,T=trains[i]
        if i == 0:
            delays[i]=X1
        else:
            k=bisect.bisect_right(times.get(A,()),S)
            delays[i]=max(0, maximum(A,k)-S)
        update(B,bisect.bisect_left(times[B],T)+1, T+delays[i])

    print(*delays[1:])

