    def update(city,k,value):
        tree=fenwick[city]
        while k < len(tree):
            if value > tree[k]:
                tree[k]=value
            k += k & -k

    def maximum(city,k):
        tree=fenwick.get(city)
        result=0
        while k:
            if tree[k] > result:
                result=tree[k]
            k -= k & -k
        return result

