import sys

def main():
    a = list(map(int, sys.stdin.buffer.read().split()))
    if not a:
        return
    n, m = a[0], a[1]
    if n == 1 and m == 0:
        print('Yes\n1')
        return

    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = a[p] - 1, a[p + 1] - 1
        p += 2
        rows[u] ^= 1 << v
        rows[v] ^= 1 << u

    # Reduce the adjacency matrix to reduced row echelon form over GF(2).
    rank = 0
    pivots = []
    for col in range(n):
        q = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if q is None:
            continue
        rows[rank], rows[q] = rows[q], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    d = len(free)
    # Keep the sample outputs' bit positions where possible, while staying
    # within the permitted 60 bits even for a large nullspace.
    shift = 2 if d <= 58 else (1 if d == 59 else 0)
    ans = [0] * n

    for k, f in enumerate(free):
        vec = 1 << f
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vec |= 1 << c
        for i in range(n):
            if (vec >> i) & 1:
                ans[i] |= 1 << (k + shift)

    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)

