from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odds = (n + 1) // 2
        evens = n // 2

        def completions(rem_odds, rem_evens, previous_parity):
            # Once the previous parity is fixed, the parity pattern is fixed.
            if previous_parity == 1:  # the next item must be even
                if rem_evens != rem_odds and rem_evens != rem_odds + 1:
                    return 0
            else:                    # the next item must be odd
                if rem_odds != rem_evens and rem_odds != rem_evens + 1:
                    return 0
            return fact[rem_odds] * fact[rem_evens]

        total = (2 if odds == evens else 1) * fact[odds] * fact[evens]
        if k > total:
            return []

        used = [False] * (n + 1)
        answer = []
        rem_odds, rem_evens = odds, evens
        previous = -1  # sentinel: there is no previous element

        for _ in range(n):
            for value in range(1, n + 1):
                parity = value & 1
                if used[value] or (previous != -1 and parity == previous):
                    continue

                no = rem_odds - parity
                ne = rem_evens - (1 - parity)
                block_size = completions(no, ne, parity)

                if k > block_size:
                    k -= block_size
                else:
                    used[value] = True
                    answer.append(value)
                    rem_odds, rem_evens, previous = no, ne, parity
                    break

        return answer

