class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # coeff[j] is the contribution modulo k of the digit at position j
        # from the left (including its mirrored position, if distinct).
        power = [1 % k] * n
        for i in range(1, n):
            power[i] = power[i - 1] * 10 % k
        coeff = [0] * half
        for j in range(half):
            coeff[j] = (power[j] +
                        (power[n - 1 - j] if j != n - 1 - j else 0)) % k

        # suffix[j] is a bit mask of all residues obtainable by positions
        # j and later, with unrestricted digits 0..9.
        suffix = [0] * (half + 1)
        suffix[half] = 1                 # residue zero
        for j in range(half - 1, -1, -1):
            c = coeff[j]
            mask = 0
            for digit in range(10):
                shift = digit * c % k
                available = suffix[j + 1]
                for residue in range(k):
                    if (available >> residue) & 1:
                        mask |= 1 << ((residue + shift) % k)
            suffix[j] = mask

        result = ['0'] * n
        remainder = 0
        for j in range(half):
            lowest = 1 if j == 0 else 0
            for digit in range(9, lowest - 1, -1):
                new_remainder = (remainder + digit * coeff[j]) % k
                needed = (-new_remainder) % k
                if (suffix[j + 1] >> needed) & 1:
                    result[j] = str(digit)
                    result[n - 1 - j] = str(digit)
                    remainder = new_remainder
                    break
        return ''.join(result)

