class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        up = [nxt]
        sm = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        for _ in range(1, levels):
            old_u, old_s = up[-1], sm[-1]
            nu = [n] * n
            ns = [0] * n
            for i in range(n):
                q = old_u[i]
                if q < n:
                    nu[i] = old_u[q]
                    ns[i] = old_s[i] + old_s[q]
                else:
                    ns[i] = old_s[i]
            up.append(nu)
            sm.append(ns)

        pref = [0]
        for x in nums:
            pref.append(pref[-1] + x)

        def cost(left, right):
            p = left
            total = 0
            for z in range(levels - 1, -1, -1):
                q = up[z][p]
                if q <= right:
                    total += sm[z][p]
                    p = q
            return total + nums[p] * (right + 1 - p) - pref[right + 1] + pref[left]

        answer = 0
        for right in range(n):
            lo, hi = 0, right
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

