class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        nxt=[n]*n
        st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]]<=nums[i]: st.pop()
            nxt[i]=st[-1] if st else n
            st.append(i)
        LOG=n.bit_length()
        ups=[nxt]
        sums=[[nums[i]*(nxt[i]-i) for i in range(n)]]
        for z in range(1,LOG):
            pu=ups[-1]; ps=sums[-1]
            u=[n]*n; s=[0]*n
            for i in range(n):
                q=pu[i]; u[i]=pu[q] if q<n else n; s[i]=ps[i]+(ps[q] if q<n else 0)
            ups.append(u); sums.append(s)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
        def cost(l,r):
            p=l; total=0
            for z in range(LOG-1,-1,-1):
                q=ups[z][p]
                if q<=r:
                    total+=sums[z][p]; p=q
            total += nums[p]*(r+1-p)
            return total-(pref[r+1]-pref[l])
        ans=0
        for r in range(n):
            lo,hi=0,r
            while lo<hi:
                m=(lo+hi)//2
                if cost(m,r)<=k: hi=m
                else: lo=m+1
            if cost(lo,r)<=k: ans+=r-lo+1
        return ans

