import sys
from functools import lru_cache

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, L = data[:3]
    values = data[3:]
    total = N + M + L
    all_mask = (1 << total) - 1
    takahashi = (1 << N) - 1
    aoki = ((1 << M) - 1) << N
    sys.setrecursionlimit(1_000_000)

    @lru_cache(None)
    def winning(t_hand, a_hand, turn):
        hand = t_hand if turn == 0 else a_hand
        if not hand:
            return False

        choices = hand
        while choices:
            played = choices & -choices
            choices -= played
            p = played.bit_length() - 1

            nt, na = t_hand, a_hand
            if turn == 0:
                nt ^= played
            else:
                na ^= played

            table = all_mask ^ (nt | na)

            # The player may choose not to take a card.
            if not winning(nt, na, turn ^ 1):
                return True

            # Or take any strictly smaller card on the table.
            candidates = table
            while candidates:
                taken = candidates & -candidates
                candidates -= taken
                q = taken.bit_length() - 1
                if values[q] < values[p]:
                    if turn == 0:
                        if not winning(nt | taken, na, 1):
                            return True
                    else:
                        if not winning(nt, na | taken, 0):
                            return True
        return False

    print("Takahashi" if winning(takahashi, aoki, 0) else "Aoki")

solve()

