class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first, middle, last = p.split('*')

        def next_occurrences(pattern):
            if not pattern:
                return None
            m = len(pattern)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            hit = [False] * (n + 1)
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    hit[i - m + 1] = True
                    j = prefix[j - 1]

            result = [n + 1] * (n + 1)
            nearest = n + 1
            for i in range(n, -1, -1):
                if hit[i]:
                    nearest = i
                result[i] = nearest
            return result

        next_first = next_occurrences(first)
        next_middle = next_occurrences(middle)
        next_last = next_occurrences(last)

        answer = n + 1
        for start in range(n + 1):
            if next_first is not None and next_first[start] != start:
                continue
            end_first = start + len(first)

            if middle:
                if end_first > n:
                    continue
                start_middle = next_middle[end_first]
            else:
                start_middle = end_first
            if start_middle > n:
                continue
            end_middle = start_middle + len(middle)

            if last:
                if end_middle > n:
                    continue
                start_last = next_last[end_middle]
            else:
                start_last = end_middle
            if start_last <= n:
                answer = min(answer, start_last + len(last) - start)

        return -1 if answer == n + 1 else answer

