import sys
import itertools


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    # Choosing the complement gives the same number of possibilities and
    # keeps the enumerated subset as small as possible.
    r = min(k, n - k)
    total = 0
    for value in a:
        total ^= value

    if r == 0:
        answer = total
    else:
        complement = k > n - k
        answer = 0
        for indices in itertools.combinations(range(n), r):
            value = 0
            for i in indices:
                value ^= a[i]
            if complement:
                value ^= total
            if value > answer:
                answer = value

    print(answer)


if __name__ == "__main__":
    main()

