G=3

def ntt(a, inv):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if inv:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        roots = [1] * half
        for k in range(1, half):
            roots[k] = roots[k - 1] * wlen % MOD
        for base in range(0, n, length):
            for k in range(half):
                u = a[base + k]
                v = a[base + half + k] * roots[k] % MOD
                a[base + k] = (u + v) % MOD
                a[base + half + k] = (u - v) % MOD
        length <<= 1
    if inv:
        z = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * z % MOD

