from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        start = [0] * n
        end = [0] * n
        post = []
        stack = [(0, 0)]
        while stack:
            x, state = stack.pop()
            if state == 0:
                start[x] = len(post)
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))
            else:
                end[x] = len(post)
                post.append(s[x])
        t = ['#'] * (2 * n + 1)
        for i, c in enumerate(post):
            t[2*i+1] = c
        rad = [0] * len(t)
        center = right = 0
        for i in range(len(t)):
            mirror = 2 * center - i
            if i < right:
                rad[i] = min(right - i, rad[mirror]) if mirror >= 0 else right-i
            while i - rad[i] - 1 >= 0 and i + rad[i] + 1 < len(t) and t[i-rad[i]-1] == t[i+rad[i]+1]:
                rad[i] += 1
            if i + rad[i] > right:
                center, right = i, i + rad[i]
        return [rad[start[i] + end[i] + 1] >= end[i] - start[i] + 1 for i in range(n)]

