import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        # All reachable values are at most 9999 under the four-digit limit.
        prime = [True] * 10000
        prime[0] = prime[1] = False
        for p in range(2, 100):
            if prime[p]:
                for v in range(p * p, 10000, p):
                    prime[v] = False

        if prime[n] or prime[m]:
            return -1

        width = len(str(n))
        place_values = [10 ** i for i in range(width)]
        inf = 10 ** 18
        distance = [inf] * 10000
        distance[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distance[value]:
                continue
            if value == m:
                return cost

            for place in place_values:
                digit = (value // place) % 10

                if digit > 0:
                    nxt = value - place
                    if not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance[nxt]:
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

                if digit < 9:
                    nxt = value + place
                    if not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance[nxt]:
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

