class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        if all(x == nums[0] for x in nums):
            ans = 0
            for i in range(1, n - 1):
                # The two conditions cover intervals [i+1,(n+i)//2]
                # and [2*i,n-1].
                a, b = i + 1, (n + i) // 2
                c, d = 2 * i, n - 1
                if b >= a:
                    ans += b - a + 1
                if d >= c:
                    ans += d - c + 1
                    if c <= b:
                        ans -= b - max(a, c) + 1
            return ans
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1
        ans = 0
        for i in range(1, n - 1):
            m = n - i
            a = nums[i:]
            zz = [0] * m
            left = right = 0
            for k in range(1, m):
                if k <= right:
                    zz[k] = min(right - k + 1, zz[k - left])
                while k + zz[k] < m and a[zz[k]] == a[k + zz[k]]:
                    zz[k] += 1
                if k + zz[k] - 1 > right:
                    left, right = k, k + zz[k] - 1
            first = z[i] >= i
            for k in range(1, m):
                j = i + k
                if (first and j >= 2 * i) or zz[k] >= k:
                    ans += 1
        return ans

