class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # In the reversed graph, reaching every node from 0 is equivalent to
        # every original node being able to reach 0.
        reverse = [[] for _ in range(n)]
        weights = set()
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.add(w)

        values = sorted(weights)

        def reachable(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

        if not values or not reachable(values[-1]):
            return -1

        lo, hi = 0, len(values) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if reachable(values[mid]):
                hi = mid
            else:
                lo = mid + 1
        return values[lo]

