class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        pairs = n // 2
        inf = 10**30

        # State (left_color, right_color) describes the outermost pair
        # processed so far, with colors encoded as left * 3 + right.
        dp = [inf] * 9
        for left in range(3):
            for right in range(3):
                if left != right:
                    dp[left * 3 + right] = cost[0][left] + cost[n - 1][right]

        transitions = [[] for _ in range(9)]
        for prev_left in range(3):
            for prev_right in range(3):
                state = prev_left * 3 + prev_right
                for left in range(3):
                    for right in range(3):
                        if (left != right and left != prev_left
                                and right != prev_right):
                            transitions[state].append(
                                (left * 3 + right, left, right)
                            )

        for i in range(1, pairs):
            new_dp = [inf] * 9
            left_cost = cost[i]
            right_cost = cost[n - 1 - i]
            for state, value in enumerate(dp):
                if value == inf:
                    continue
                for next_state, left, right in transitions[state]:
                    candidate = value + left_cost[left] + right_cost[right]
                    if candidate < new_dp[next_state]:
                        new_dp[next_state] = candidate
            dp = new_dp

        return min(dp)

